//! Centralized host thunk metadata, guest pointer helpers, and subsystem
//! organization for the PE runtime dispatch layer.
//!
//! This module provides:
//! - [`ThunkMetadata`] — centralized metadata for each host thunk (name,
//!   subsystem, argument count, last-error behavior, implementation quality,
//!   guest-architecture mask, minimum Windows version, support policy).
//! - [`Subsystem`] — enumeration of host thunk subsystems for modular
//!   organization.
//! - [`LastErrorBehavior`] — describes how a thunk affects `GetLastError`.
//! - [`SupportPolicy`] — the generic (non-Steam-specific) user-mode profile
//!   classification of every thunk.
//! - [`ImplementationLevel`] — classifies how completely a host thunk is
//!   implemented (used by import-coverage diagnostics).
//! - [`THUNK_METADATA`] — the canonical per-DLL thunk metadata table covering
//!   EVERY exported API Casa1 actually registers (the runtime's
//!   `pe_runtime::export_tables()` surface plus the host-thunk dispatch
//!   surface), not just one fixture's imports.
//! - Guest pointer read/write helpers with bounds checking, overflow
//!   protection, and partial-write detection.
//!
//! # Design Goals
//!
//! 1. **Single source of truth** for thunk metadata so argument counts, names,
//!    and last-error behavior stay consistent across dispatch, testing, and
//!    diagnostics.  The parity test in tests/section45_thunk_metadata.rs
//!    asserts that [`THUNK_METADATA`] and the runtime's registered export
//!    surface cover exactly the same (DLL, export) pairs — there is no
//!    unaccounted host thunk and no orphan metadata entry.
//! 2. **Safe guest memory access** through validated pointer helpers that
//!    replace ad-hoc `memory.read_u32(...)` calls with bounds-checked
//!    alternatives.
//! 3. **Subsystem-level organization** enabling future modular splitting of
//!    `pe_runtime.rs` by grouping thunks into logical categories.

use crate::api_database::WindowsVersion;
use crate::cpu::GuestArch;
use crate::cpu::MemoryImage;
use crate::error::AppError;
use crate::reason::ReasonCode;
use serde::{Deserialize, Serialize};

// ---------------------------------------------------------------------------
// Subsystem enumeration
// ---------------------------------------------------------------------------

/// Subsystem categories for host thunks.
///
/// Each thunk belongs to exactly one subsystem, which determines its
/// logical grouping for modular dispatch, testing, and documentation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Subsystem {
    /// Core Win32 kernel APIs (kernel32.dll, kernelbase.dll, ntdll.dll).
    Kernel,
    /// User32 window management and GDI (user32.dll, gdi32.dll).
    User32,
    /// Network APIs (ws2_32.dll, winhttp.dll, wininet.dll).
    Network,
    /// Graphics APIs (d3d11.dll, d3d12.dll, dxgi.dll, d3d9.dll).
    Graphics,
    /// Audio APIs (xaudio2_*.dll, dsound.dll).
    Audio,
    /// COM / OLE automation (ole32.dll, oleaut32.dll).
    Com,
    /// Shell and filesystem (shell32.dll, shlwapi.dll, advapi32.dll).
    Shell,
    /// Steam API (steam_api64.dll, steam_api.dll).
    Steam,
    /// Direct2D / DirectWrite (d2d1.dll, dwrite.dll).
    D2D,
    /// WebView2 (webview2.dll).
    WebView2,
    /// WMI (wbem*.dll).
    Wmi,
    /// Security and cryptography (bcrypt.dll, crypt32.dll).
    Security,
    /// C runtime (msvcrt.dll, ucrtbase.dll, vcruntime*.dll).
    Crt,
    /// Diagnostics and telemetry.
    Diagnostics,
    /// Internal runtime helpers (guest object management, delay-load).
    Runtime,
}

// ---------------------------------------------------------------------------
// Last-error behavior
// ---------------------------------------------------------------------------

/// Describes how a host thunk affects the Win32 last-error value.
///
/// Windows API functions fall into several categories regarding
/// `GetLastError` / `SetLastError`:
///
/// - **SetsOnFailure**: The thunk calls `SetLastError` with a specific code
///   when it fails, and clears it to zero on success.
/// - **SetsOnSuccess**: The thunk writes the last-error value on the success
///   path (typically clearing it to zero) even though the API is documented
///   as never failing.
/// - **SetsAlways**: The thunk always sets last-error (even on success).
/// - **Preserves**: The thunk never modifies last-error.
/// - **UndefinedOnSuccess**: The thunk sets a specific code on failure; on
///   success the value is undefined — Windows documents that callers must
///   only inspect `GetLastError` after failure.  This is the classification
///   of the majority of boolean-returning APIs.
/// - **Unknown**: Temporary seed only — a metadata entry still awaiting its
///   audit.  The final table must never ship entries with this class; the
///   count of remaining `Unknown` entries is reported by the parity test.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LastErrorBehavior {
    /// Sets last-error on failure; clears to zero on success.
    SetsOnFailure,
    /// Sets last-error even on success (typically to zero).
    SetsOnSuccess,
    /// Always sets last-error regardless of outcome.
    SetsAlways,
    /// Never modifies last-error.
    Preserves,
    /// Sets a specific code on failure; undefined on success — callers must
    /// only inspect after failure.
    UndefinedOnSuccess,
    /// Not yet audited — assume it may modify last-error.
    Unknown,
}

// ---------------------------------------------------------------------------
// Architecture mask
// ---------------------------------------------------------------------------

/// The guest architectures a host thunk supports.
///
/// `ANY` is the default for thunks that behave identically under both guest
/// architectures; per-architecture restrictions are recorded explicitly so
/// coverage accounting can tell which guest arch an API actually works on.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ArchMask {
    /// The thunk supports 32-bit (x86) guests.
    pub x86: bool,
    /// The thunk supports 64-bit (x64) guests.
    pub x64: bool,
}

impl ArchMask {
    /// Both guest architectures.
    pub const ANY: Self = Self {
        x86: true,
        x64: true,
    };
    /// 32-bit (x86) guests only.
    pub const X86_ONLY: Self = Self {
        x86: true,
        x64: false,
    };
    /// 64-bit (x64) guests only.
    pub const X64_ONLY: Self = Self {
        x86: false,
        x64: true,
    };

    /// Whether the mask covers the given guest architecture.
    pub const fn supports(self, arch: GuestArch) -> bool {
        match arch {
            GuestArch::X86 => self.x86,
            GuestArch::X64 => self.x64,
        }
    }
}

// ---------------------------------------------------------------------------
// Support policy
// ---------------------------------------------------------------------------

/// The generic support-policy classification of a host thunk within the
/// user-mode compatibility profile.
///
/// This replaces the former Steam-bootstrap-criticality flag: the concept is
/// now generic (any user-mode application, not Steam specifically).
///
/// - [`SupportPolicy::Required`] — the core kernel32/ntdll/user32 APIs that
///   any user-mode application needs; a runtime-reached `Required` API whose
///   implementation is `Stub`/`Unsupported` fails the release gate.
/// - [`SupportPolicy::OptionalFeature`] — a subsystem the profile does not
///   need unless the guest uses it (graphics, audio, network subsystems,
///   Steam API, WebView2, ...).  Passes the profile-sensitive completeness
///   gate when the profile explicitly excludes the feature.
/// - [`SupportPolicy::OutsideUserModeProfile`] — kernel/DRM/anti-cheat
///   adjacent APIs (native `Nt*` layer, kernel thunk layers like d3d8thk,
///   ...) that are exempt from the user-mode tier's completeness gate.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, Default)]
pub enum SupportPolicy {
    /// Core user-mode API any application needs.
    #[default]
    Required,
    /// Optional subsystem; excluded features may pass the gate.
    OptionalFeature,
    /// Kernel/DRM/anti-cheat adjacent; outside the user-mode profile.
    OutsideUserModeProfile,
}

// ---------------------------------------------------------------------------
// Implementation quality
// ---------------------------------------------------------------------------

/// Classifies how completely a host thunk is implemented.
///
/// This is the implementation-quality axis of the canonical [`ThunkMetadata`]
/// table.  It is consumed by the import-coverage diagnostics
/// ([`crate::import_coverage::coverage_for_steam_fixture`]) and by the
/// section24 integration model, which reports every Steam.exe import against
/// it and encodes the release requirement that no *runtime-reached*
/// Steam-critical API be `Stub` or `Unsupported`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum ImplementationLevel {
    /// The thunk is documented as complete: it reads its arguments, performs
    /// the real operation against runtime state, writes guest-visible
    /// results, and reports errors through `last_error`.
    Implemented,
    /// The thunk has a real implementation with known limitations documented
    /// in the dispatch code (e.g. plausible/synthetic values, a restricted
    /// subset of codes or formats, unsupported edge cases that degrade
    /// gracefully).
    Partial,
    /// The thunk is a placeholder/no-op: it returns a canned value (or
    /// ignores its arguments) and performs no meaningful operation.
    Stub,
    /// There is no host thunk for this API — dispatch would fail (the
    /// import maps to `HostThunk::Unsupported` or to nothing at all).
    Unsupported,
}

impl ImplementationLevel {
    /// `true` when the level is `Implemented` or `Partial` — i.e. the API
    /// has at least a working host thunk.
    pub fn has_working_implementation(self) -> bool {
        matches!(
            self,
            ImplementationLevel::Implemented | ImplementationLevel::Partial
        )
    }
}

// ---------------------------------------------------------------------------
// Thunk metadata
// ---------------------------------------------------------------------------

/// Static metadata for a single host thunk.
///
/// This struct centralizes information that was previously scattered across
/// the `HostThunk::x86_arg_bytes()` match arms and dispatch code.
#[derive(Debug, Clone)]
pub struct ThunkMetadata {
    /// Exporting DLL name (lowercase, with extension, e.g. `"kernel32.dll"`).
    pub dll: &'static str,
    /// Human-readable API name (e.g., `"CreateFileW"`).
    pub name: &'static str,
    /// Subsystem this thunk belongs to.
    pub subsystem: Subsystem,
    /// Total size of all arguments in bytes for x86 (32-bit) calling convention.
    /// For x64, arguments are passed in registers (RCX, RDX, R8, R9) and then
    /// stack, so this is primarily used for x86 stack cleanup.
    pub x86_arg_bytes: u32,
    /// How this thunk affects `GetLastError` (explicitly classified; the
    /// table never ships `Unknown` — see [`LastErrorBehavior`]).
    pub last_error: LastErrorBehavior,
    /// Implementation quality classification (see [`ImplementationLevel`]).
    pub implementation: ImplementationLevel,
    /// Guest architectures this thunk supports.
    pub architectures: ArchMask,
    /// Minimum Windows version the thunk provides compatibility for.
    pub min_windows_version: WindowsVersion,
    /// Generic user-mode profile classification (replaces the former
    /// Steam-bootstrap-criticality flag).  A runtime-reached `Required` API
    /// classified `Stub`/`Unsupported` fails the release requirement encoded
    /// in tests/section24.rs and the profile-sensitive completeness gate in
    /// api_database.rs.
    pub support_policy: SupportPolicy,
}

/// Convenience constructor for [`THUNK_METADATA`] entries.
///
/// Every table entry carries an explicit [`LastErrorBehavior`] (never
/// `Unknown`), an [`ArchMask`], a minimum [`WindowsVersion`], and a
/// [`SupportPolicy`].
#[allow(clippy::too_many_arguments)]
const fn meta(
    dll: &'static str,
    name: &'static str,
    x86_arg_bytes: u32,
    subsystem: Subsystem,
    last_error: LastErrorBehavior,
    implementation: ImplementationLevel,
    architectures: ArchMask,
    min_windows_version: WindowsVersion,
    support_policy: SupportPolicy,
) -> ThunkMetadata {
    ThunkMetadata {
        dll,
        name,
        subsystem,
        x86_arg_bytes,
        last_error,
        implementation,
        architectures,
        min_windows_version,
        support_policy,
    }
}

/// Canonical host-thunk metadata table.
///
/// Covers EVERY exported API Casa1 actually registers — the runtime's
/// registered export surface (`pe_runtime::export_tables()`) plus the
/// host-thunk dispatch surface — not just the tracked Steam.exe fixture's
/// imports.  The bidirectional parity with `export_tables()` is asserted in
/// tests/section45_thunk_metadata.rs: every registered export has a metadata
/// entry and every metadata entry is a registered export; there is no
/// unaccounted host thunk.
///
/// Implementation levels were assigned from the dispatch code in
/// `pe_runtime.rs` and, for the registered export surface, probed from the
/// runtime's import-name tables (`HostThunk::from_import`):
///
/// - **Implemented** — complete, real behavior (arguments read, guest state
///   updated, results/errors reported).
/// - **Partial** — real behavior with documented limitations (plausible
///   values, restricted code/format subsets, unsupported edges degrade
///   gracefully).
/// - **Stub** — canned/no-op placeholders that return fixed values.
/// - **Unsupported** — no host thunk exists for the API.
///
/// `support_policy` classifies every thunk against the generic user-mode
/// profile: `Required` marks the core kernel32/ntdll/user32 APIs any
/// user-mode application needs (process/thread/IO/handle basics, window and
/// message loop, named pipes, winsock basics, registry, COM/OLE init, CRT
/// malloc/free/_beginthreadex/errno, TLS, and the sync-primitive family);
/// `OptionalFeature` marks optional subsystems; `OutsideUserModeProfile`
/// marks kernel/DRM/anti-cheat adjacent entries.
